          if (t.key) { const p = V(f.attrs[t.parent]?.[0]); put(V(name), V(f.attrs[t.key]?.[0]) ?? 'is_a', V(f.attrs[t.value]?.[0]) ?? p, t.type); put(V(name), 'is_a', p, t.type); continue; }
